      .where(eq(users.firebaseUid, uid))
      .limit(1);

    if (!dbUser && email) {
      // Check by email in case user was created before signing up
      [dbUser] = await db
        .select()
        .from(users)
        .where(eq(users.email, email))
        .limit(1);

      if (dbUser) {
        // Link existing user to Firebase account
        [dbUser] = await db
          .update(users)
          .set({
            firebaseUid: uid,
            firstName: displayName.split(" ")[0] || dbUser.firstName,
            lastName: displayName.split(" ").slice(1).join(" ") || dbUser.lastName,
          })
          .where(eq(users.id, dbUser.id))
          .returning();
      } else {
        // Create new user
        const nameParts = displayName.split(" ");
        [dbUser] = await db
          .insert(users)
          .values({
            firebaseUid: uid,
            email,
            firstName: nameParts[0] || "",
            lastName: nameParts.slice(1).join(" ") || "",
            phone: null,
          })
          .onConflictDoUpdate({
            target: users.firebaseUid,
            set: { email, updatedAt: new Date() },
          })
          .returning();
      }
    }

    if (!dbUser) return null;

    // Link orphaned requests by email
    const linkedRequests = await db
      .update(fobRequests)
      .set({ requesterId: dbUser.id })
      .where(
        and(
          eq(fobRequests.orphanEmail, dbUser.email),
          isNull(fobRequests.requesterId)
        )
      )
      .returning({ orphanFirstName: fobRequests.orphanFirstName, orphanLastName: fobRequests.orphanLastName });
