export const MERGE_SPECIAL_COLUMNS: readonly (readonly [table: string, column: string])[] = [
  ["tenant_memberships", "user_id"],
  ["admin_assignments", "user_id"],
  ["notification_preferences", "user_id"],
];

/** Unique indexes containing a user id column, each handled by name above. */
export const MERGE_HANDLED_UNIQUE_INDEXES: readonly string[] = [
  "tenant_memberships_tenant_id_user_id_unique",
  "admin_assignments_tenant_id_user_id_unique",
  "notification_preferences_tenant_id_user_id_notification_type_un",
];

