export class MemberMergeError extends Error {
  constructor(
    "notification_preferences.user_id",
    rowCount(
      await tx.execute(
        sql`update notification_preferences set user_id = ${targetUserId} where user_id = ${sourceUserId}`
      )
    )
  );

  // 4. Confirmations: never leave two live confirmations for the same thing.
  // The duplicate's pending one is cancelled (status "cancelled", the same
  // state the admin Cancel confirmation action sets) when the kept member
  // already has a pending one for the same club, season and scope.
  const pending = await tx
    .select()
    .from(attestationRequests)
    .where(
      and(
        eq(attestationRequests.tenantId, tenantId),
        eq(attestationRequests.status, "pending"),
        inArray(attestationRequests.userId, [targetUserId, sourceUserId])
      )
    );
  const scopeKey = (a: (typeof pending)[number]) =>
    `${a.season}|${a.credentialIds?.length ? [...a.credentialIds].sort().join(",") : "all"}`;
  const keptKeys = new Set(pending.filter((a) => a.userId === targetUserId).map(scopeKey));
  const cancelIds = pending
    .filter((a) => a.userId === sourceUserId && keptKeys.has(scopeKey(a)))
    .map((a) => a.id);
  if (cancelIds.length > 0) {
    await tx
      .update(attestationRequests)
      .set({ status: "cancelled", updatedAt: new Date() })
      .where(inArray(attestationRequests.id, cancelIds));
    bump("attestation_requests (duplicate pending confirmation cancelled)", cancelIds.length);
  }

  // 5. Emails. The duplicate's primary and additional addresses become
  // additional addresses of the kept member. Its Firebase uid goes on the row
  // for its former primary so that sign-in resolves straight to the kept
